import Link from 'next/link'

import { PersonaBadge } from '@/components/personas/persona-badge'
import { featureFlags } from '@/lib/feature-flags'

/**
 * An AI expert's list says it was made by AI (spec-ai-expert-personas.md, UI
 * requirement 4) — the desktop line under the list: the AI chip, then
 * "Generated by FieldScout AI as <name> — a fictional, parody analyst persona
 * not affiliated with any real person." The name links to the expert's page
 * while that surface is on.
 *
 * One line for both desktop pages that show someone's list: the public share
 * page (server-rendered, the expert read on the server) and Community's list
 * page in the app (plan C5, the expert read with `useListPersona`). The phone
 * says the same in its own language (`ListAiAttribution`).
 *
 * `persona` undefined: the expert hasn't been read yet, or couldn't be — the
 * line still says the list is AI-made, never dropped because a read failed.
 * A switched-off expert's list gets no line at all: the caller doesn't
 * render this.
 *
 * Not a client component: the share page renders it on the server.
 */
export function ListAiNote({ persona }: { persona?: { username: string; display_name: string } }) {
  return (
    <div
      className="flex flex-wrap items-center justify-center gap-2 text-[11px] font-medium text-n-3"
      data-list-ai-note
    >
      <PersonaBadge />
      <span>
        {persona ? (
          <>
            Generated by FieldScout AI as{' '}
            {/* The persona profile is release-gated out of the 2026 go-live
                scope; the AI disclosure itself always stays — only the link
                to the (hidden) profile drops. */}
            {featureFlags.personas ? (
              <Link href={`/personas/${persona.username}`} className="font-bold text-ink hover:underline">
                {persona.display_name}
              </Link>
            ) : (
              <span className="font-bold text-ink">{persona.display_name}</span>
            )}{' '}
            — a fictional, parody analyst persona not affiliated with any real person.
          </>
        ) : (
          'Generated by FieldScout AI.'
        )}
      </span>
    </div>
  )
}
